INSERT INTO public.tools_catalog (id, name, description, category, tool_types, source, is_live, is_premium, is_free, dedicated_route, display_order, extra_categories)
VALUES
  ('maa-ki-virasat', 'Maa ki Virasat', 'Capture your mother''s life, recipes, sayings and wisdom by voice, and get a beautiful legacy book the whole family will treasure.', 'Personal', ARRAY['Legacy Book', 'Storytelling'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('grandparents-story-book', 'Grandparents'' Story Book', 'Record your grandparents'' stories through guided questions and turn them into an illustrated-style story book for the grandchildren.', 'Personal', ARRAY['Legacy Book', 'Storytelling'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('family-tree-and-history-studio', 'Family Tree and History Studio', 'Build your family tree and history through a conversation: generations, migrations, occupations, traditions and stories, in one book.', 'Personal', ARRAY['Genealogy', 'Legacy Book'], 'featured', true, false, false, NULL, 0, ARRAY['Home, Family & Travel']),
  ('babys-first-year-book', 'Baby''s First Year Book', 'Turn notes from your baby''s first year into a keepsake book: birth story, monthly milestones, firsts, family wishes and letters.', 'Personal', ARRAY['Baby Book', 'Keepsake'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('wedding-planner-studio', 'Wedding Planner Studio', 'Plan an Indian wedding end to end: function list, budget split, vendor checklist, guest planning, timeline and day-of schedules.', 'Home, Family & Travel', ARRAY['Wedding', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('our-love-story-book', 'Our Love Story Book', 'Tell your love story through guided questions and get a romantic keepsake book for an anniversary, wedding or proposal.', 'Personal', ARRAY['Keepsake', 'Storytelling'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('tribute-and-memorial-book', 'Tribute and Memorial Book', 'Gently gather memories of a loved one who has passed and create a tribute book for the family, prayer meeting or anniversary.', 'Personal', ARRAY['Memorial', 'Legacy Book'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('family-recipe-book', 'Family Recipe Book', 'Record family recipes by voice, the way they are really made, and get a recipe book with exact measures, stories and a cover.', 'Personal', ARRAY['Recipes', 'Keepsake'], 'featured', true, false, false, NULL, 0, ARRAY['Home, Family & Travel']),
  ('letters-to-my-child', 'Letters to My Child', 'Write heartfelt letters to your child for future milestones, like their 10th, 18th birthday, wedding day, with guided prompts.', 'Personal', ARRAY['Letters', 'Keepsake'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('career-memoir-studio', 'Career Memoir Studio', 'Turn a long career into a memoir: journey, turning points, lessons, people who mattered, for retirement, family or publishing.', 'Personal', ARRAY['Memoir', 'Storytelling'], 'featured', true, false, false, NULL, 0, ARRAY['Jobs & Careers']),
  ('farewell-tribute-book', 'Farewell Tribute Book', 'Make a farewell or retirement book for a colleague, teacher or boss from team memories, with a speech and messages.', 'Personal', ARRAY['Farewell', 'Keepsake'], 'featured', true, false, false, NULL, 0, ARRAY['HR & Staffing']),
  ('parenting-coach', 'Parenting Coach', 'A calm, practical parenting coach for tantrums, screen time, studies, teens, sibling fights and more, ending with a home plan.', 'Home, Family & Travel', ARRAY['Parenting', 'Coaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('elder-care-planner', 'Elder Care Planner', 'Plan care for ageing parents: health and medicine routine, home safety, caregiver options, money, documents and an emergency plan.', 'Home, Family & Travel', ARRAY['Elder Care', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Health & Wellness']),
  ('family-emergency-file', 'Family Emergency File', 'Organise everything your family would need in an emergency: accounts, policies, documents, contacts, passwords plan and instructions.', 'Home, Family & Travel', ARRAY['Organisation', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Money & Planning']),
  ('family-function-planner', 'Family Function Planner', 'Plan a birthday, griha pravesh, mundan, anniversary or puja: guest list, menu, budget, vendor checklist, schedule and invitations.', 'Home, Family & Travel', ARRAY['Events', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('couple-life-planner', 'Couple Life Planner', 'A guided session for couples to align on money, home, careers, kids, families and time, ending with a shared life plan.', 'Home, Family & Travel', ARRAY['Relationships', 'Coaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('kids-art-book', 'Kids Art Book', 'Upload photos of your child''s drawings to get a curated art book: titles, the story behind each piece, captions and a book layout.', 'Personal', ARRAY['Kids', 'Keepsake'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('village-roots-book', 'Village Roots Book', 'Record the story of your ancestral village by voice: its people, places, festivals, food and changes, written as a heritage book.', 'Personal', ARRAY['Heritage', 'Legacy Book'], 'featured', true, false, false, NULL, 0, ARRAY['Home, Family & Travel']),
  ('occasion-speech-coach', 'Occasion Speech Coach', 'Write and rehearse a speech for a wedding, birthday, farewell or award: drafted from your stories, then practised by voice with feedback.', 'Home, Family & Travel', ARRAY['Speeches', 'Coaching'], 'featured', true, false, false, NULL, 0, ARRAY['Personal']),
  ('pet-life-book', 'Pet Life Book', 'Write your pet''s life story: how they came home, their habits, adventures and the love they bring, as a keepsake or memorial book.', 'Personal', ARRAY['Pets', 'Keepsake'], 'featured', true, false, false, NULL, 0, '{}'::text[])
